import Foundation
import AppKit
import CryptoKit

/// Filters + captures NSPasteboard changes into the encrypted vault.
/// Polls 4×/sec (OpenKey-Raycast hybrid: cheap, robust, no XPC boldness).
final class ClipboardCaptureService {
    private var timer: Timer?
    private var lastChangeCount: Int = NSPasteboard.general.changeCount
    private var lastContentHash = Data()

    /// Concealed / transient / auto-generated — the spec'd pasteboard
    /// contracts never contain user-visible copy (password managers, 1P,
    /// Keychain-synced secrets, ASCII waveform that only services share).
    static let concealMarkers: [String] = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    func start() {
        lastChangeCount = NSPasteboard.general.changeCount
        let timer = Timer(timeInterval: 0.25, repeats: true) { [weak self] _ in
            self?.tick()
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Runs on main (pasteboard access is main-thread friendly).
    private func tick() {
        let pasteboard = NSPasteboard.general
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        lastChangeCount = changeCount

        guard isGenerallyCapturable(pasteboard) else { return }
        guard let entry = Self.readEntry(pasteboard) else { return }

        // Dedup consecutive duplicates (copy same file twice…).
        let hash = entry.payloadHash()
        guard hash != lastContentHash else { return }
        lastContentHash = hash

        let bundleID = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? ""
        switch entry.kind {
        case .text:
            let text = entry.text
            guard !text.isEmpty else { return }
            _ = ClipboardStore.shared.insert(kind: .text, payload: Data(text.utf8), bundleID: bundleID)
        case .image:
            _ = ClipboardStore.shared.insert(kind: .image, payload: entry.imageData, bundleID: bundleID)
        case .fileURL:
            let url = entry.fileURL
            _ = ClipboardStore.shared.insert(kind: .fileURL, payload: Data(url.absoluteString.utf8), bundleID: bundleID)
        }

        ClipboardStore.shared.prune(keep: AppSettings.shared.clipboardRetentionLimit)
    }

    /// True unless a concealed/transient marker exists.
    private func isGenerallyCapturable(_ pasteboard: NSPasteboard) -> Bool {
        for marker in Self.concealMarkers {
            if pasteboard.data(forType:NSPasteboard.PasteboardType(marker)) != nil { return false }
        }
        return true
    }

    private static func readEntry(_ pasteboard: NSPasteboard) -> ClipboardEntry? {
        var entry = ClipboardEntry(id: -1, kind: .text, createdAt: Date(), sourceBundleID: "")

        if let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff) {
            entry.kind = .image
            entry.imageData = data
            return entry
        }
        if let urlRaw = pasteboard.string(forType: .fileURL), let url = URL(string: urlRaw) {
            entry.kind = .fileURL
            entry.fileURL = url
            return entry
        }
        if let text = pasteboard.string(forType: .string) {
            entry.kind = .text
            entry.text = text
            return entry
        }
        return nil
    }
}

private extension ClipboardEntry {
    func payloadHash() -> Data {
        switch kind {
        case .text:
            return Data(SHA256.hash(data: Data(text.utf8)))
        case .image:
            // Hash some deterministic bytes: size + first/last 512 B.
            var h = [UInt8](String(imageData.count).utf8)
            h += Array(imageData.prefix(512)).map { $0 }
            h += Array(imageData.suffix(512)).map { $0 }
            return Data(h)
        case .fileURL:
            return Data(fileURL.absoluteString.utf8)
        }
    }
}

/// Puts a clipboard entry back on the pasteboard and triggers paste in the
/// frontmost app (cmd+V targeted at the pid only).
enum ClipboardPaster {
    static func paste(_ entry: ClipboardEntry) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        switch entry.kind {
        case .text:
            pasteboard.setString(entry.text, forType: .string)
        case .image:
            pasteboard.setData(entry.imageData, forType: .png)
        case .fileURL:
            pasteboard.setData(Data(entry.fileURL.absoluteString.utf8), forType: .fileURL)
        }
        ClipboardStore.shared.touchLastUsed(id: entry.id)

        guard let app = NSWorkspace.shared.frontmostApplication else { return }
        let pid = app.processIdentifier
        // cmd + v
        let source = CGEventSource(stateID: .privateState)
        if let vDown = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: true),
           let vUp = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: false) {
            vDown.flags = .maskCommand
            vUp.flags = .maskCommand
            vDown.postToPid(pid)
            vUp.postToPid(pid)
        }
    }
}
